const $=id=>document.getElementById(id),canvas=$('world'),city=new CityRenderer(canvas),mini=$('mini').getContext('2d');
const audio=new DriveAudio();
let simulation=new FixedVehicleLoop(cars[0]),state=simulation.state,renderState=state,car=0,draftCar=0,mode='demo',draftMode='demo',locationId='times-square',draftLocation='times-square',playing=false,paused=false,optionsOpen=false,introActive=true,mph=true,keys={},last=0,controls={},time=0,collisionCooldown=0,prevCheckpoint=0,optionSnapshot=null,optionsReturnPaused=false;
const carSVG=color=>`<svg viewBox="0 0 130 50" aria-hidden="true"><path d="M9 32l10-10 24-3 13-13h38l17 15 12 4 1 13H9z" fill="${color}"/><path d="M55 10h35l12 11H42z" fill="#16202d"/><circle cx="31" cy="36" r="10" fill="#080e17"/><circle cx="104" cy="36" r="10" fill="#080e17"/><circle cx="31" cy="36" r="5" fill="#8794a4"/><circle cx="104" cy="36" r="5" fill="#8794a4"/></svg>`;
$('cars').innerHTML=cars.map((c,i)=>`<button class="carcard ${i===0?'selected':''}" data-car="${i}" aria-pressed="${i===0}">${carSVG(['#bec8cf','#829bb0','#ba895a'][i])}<div><strong>${c.name}</strong><small>${c.type} · ${Math.round(c.max*2.237)} MPH</small></div><em>${i===0?'✓':''}</em></button>`).join('');
function selectCar(i){draftCar=i;document.querySelectorAll('[data-car]').forEach(b=>{const selected=+b.dataset.car===i;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));b.querySelector('em').textContent=selected?'✓':'';});}
document.querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>selectCar(+b.dataset.car));
function tab(name){document.querySelectorAll('[data-tab]').forEach(b=>{const yes=b.dataset.tab===name;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',String(yes));});for(const n of ['vehicle','location','driving'])$(n+'Tab').hidden=n!==name;}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
function chooseMode(){mode='demo';draftMode='demo';}
$('locations').innerHTML=locations.map(l=>`<button class="location-card" data-location="${l.id}" aria-pressed="${l.id===locationId}"><svg viewBox="0 0 120 70" aria-hidden="true"><rect width="120" height="70" fill="#101c25"/>${l.id==='soho'?'<path d="M5 60V20h25v40m3 0V10h28v50m3 0V16h25v44" fill="#a2957d"/><path d="M8 28h78M8 40h78M8 52h78" stroke="#d3c7b1"/>':l.id==='times-square'?'<path d="M8 60V20h25v40m6 0V5h17v55m5 0V15h23v45m5 0V10h23v50" fill="#4d6678"/><path d="M13 35h20M40 20h14M40 33h14M63 28h20M90 35h21" stroke="#d57caa" stroke-width="8"/>':'<path d="M5 50V20h30v30m5 0V12h25v38m8 0V19h32v31" fill="#50687a"/><path d="M12 58h95M12 64h95" stroke="#d4dde0" stroke-width="3"/><path d="M44 24h17M76 27h27" stroke="#8c85cf" stroke-width="9"/>'}</svg><div><strong>${l.name}</strong><small>${l.city} · ${l.street}</small></div><span>${l.id===locationId?'✓':''}</span></button>`).join('');
function selectLocation(id){if(!locations.some(l=>l.id===id))throw Error('Unknown location');draftLocation=id;document.querySelectorAll('[data-location]').forEach(b=>{let selected=b.dataset.location===id;b.setAttribute('aria-pressed',String(selected));b.classList.toggle('selected',selected);b.querySelector('span').textContent=selected?'✓':'';});}
document.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>selectLocation(b.dataset.location));selectLocation(locationId);
function start(){playing=true;paused=false;optionsOpen=false;simulation=new FixedVehicleLoop(cars[car]);state=simulation.state;renderState=state;time=0;prevCheckpoint=0;collisionCooldown=0;controls={};keys={};$('garage').hidden=true;$('hud').hidden=false;$('pauseDialog').hidden=true;document.body.classList.remove('options-open');$('street').style.display=mode==='google'?'block':'none';document.body.classList.add('playing');document.body.classList.toggle('street-playing',mode==='google');}
function reset(){simulation=new FixedVehicleLoop(cars[car]);state=simulation.state;renderState=state;time=0;prevCheckpoint=0;collisionCooldown=0;controls={};keys={};}
function pause(value=!paused){if(!playing||introActive||optionsOpen)return;paused=value;keys={};$('pauseDialog').hidden=!value;if(value)$('resume').focus();}
function openOptions(){if(introActive||optionsOpen)return;optionsReturnPaused=paused;paused=true;keys={};controls={};optionsOpen=true;selectCar(car);selectLocation(locationId);optionSnapshot=Object.fromEntries(['transmission','preset','traffic','sound'].map(id=>[id,$(id).value]));$('pauseDialog').hidden=true;$('garage').hidden=false;document.body.classList.add('options-open');tab('vehicle');$('closeOptions').focus();}
function closeOptions(apply=false){if(!optionsOpen)return;if(apply){const changed=car!==draftCar||locationId!==draftLocation;car=draftCar;locationId=draftLocation;if(changed){start();$('menuBtn').focus();return;}}else{for(const [id,v] of Object.entries(optionSnapshot||{}))$(id).value=v;selectCar(car);selectLocation(locationId);}
optionsOpen=false;$('garage').hidden=true;document.body.classList.remove('options-open');paused=optionsReturnPaused;keys={};$('pauseDialog').hidden=!paused;(paused?$('resume'):$('menuBtn')).focus();}
$('drive').onclick=()=>closeOptions(true);$('closeOptions').onclick=$('cancelOptions').onclick=()=>closeOptions(false);$('reset').onclick=reset;$('pause').onclick=()=>pause();$('resume').onclick=()=>pause(false);$('restart').onclick=()=>{reset();pause(false);};$('back').onclick=openOptions;$('menuBtn').onclick=openOptions;$('units').onclick=()=>{mph=!mph;$('units').textContent=mph?'MPH':'KPH';};$('about').onclick=()=>$('aboutDialog').showModal();$('closeAbout').onclick=()=>$('aboutDialog').close();
function dismissIntro(){if(!introActive)return;introActive=false;$('boot').classList.add('fading');document.body.classList.remove('booting');paused=document.hidden;$('pauseDialog').hidden=!paused;setTimeout(()=>{$('boot').hidden=true;},850);}
$('boot').onclick=dismissIntro;$('boot').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();dismissIntro();}};
window.addEventListener('keydown',e=>{audio.unlock();const k=e.key.toLowerCase();if(introActive){if(k==='enter'||k===' '){e.preventDefault();dismissIntro();}return;}
if($('aboutDialog').open)return;
if(optionsOpen){if(k==='escape'){e.preventDefault();closeOptions(false);}if(k==='tab'){const focus=[...$('garage').querySelectorAll('button,input,select,a')].filter(x=>!x.disabled&&x.getClientRects().length);const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}
if(!playing||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(k==='escape'){e.preventDefault();pause();return;}if(paused)return;if([' ','arrowup','arrowdown','arrowleft','arrowright','shift'].includes(k))e.preventDefault();if(k==='r'){reset();return;}keys[k]=true;});
window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>pause(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{if(paused||introActive)return;audio.unlock();e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true;};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false;});
function render(dt){
city.update(renderState,{...controls,motionActive:!paused&&!optionsOpen&&!introActive,braking:keys.s||keys.arrowdown},time,dt,optionsOpen?draftCar:car,playing&&!optionsOpen,$('preset').value,$('traffic').value,optionsOpen?draftLocation:locationId);
mini.fillStyle='#0b1720';mini.fillRect(0,0,180,150);mini.strokeStyle='#445264';mini.lineWidth=14;mini.beginPath();for(let i=0;i<150;i++){let x=90+0;i?mini.lineTo(x,150-i):mini.moveTo(x,150-i);}mini.stroke();mini.fillStyle='#d8e9ef';mini.beginPath();mini.moveTo(90,100);mini.lineTo(83,115);mini.lineTo(97,115);mini.fill();
}
function contacts(s){const config=cars[car],loc=locations.find(l=>l.id===locationId),width=loc.halfWidth,extent=.95*Math.abs(Math.cos(s.orientation.yaw))+2.1*Math.abs(Math.sin(s.orientation.yaw)),edge=width-extent;
if(Math.abs(s.position.x)>edge)resolveContact(s,config,{normal:{x:-Math.sign(s.position.x),z:0},point:{x:Math.sign(s.position.x)*.95,z:0},penetration:Math.abs(s.position.x)-edge,restitution:.1});
const obstacle=(x,z,velocity=0)=>{const gapX=s.position.x-x,gapZ=z-s.position.z;if(Math.abs(gapX)>extent+1||Math.abs(gapZ)>4.3)return;const lateral=(extent+1-Math.abs(gapX))<(4.3-Math.abs(gapZ));const normal=lateral?{x:Math.sign(gapX)||1,z:0}:{x:0,z:-Math.sign(gapZ)||-1};resolveContact(s,config,{normal,point:{x:normal.x?-.95*normal.x:0,z:normal.z?-2*normal.z:0},penetration:lateral?extent+1-Math.abs(gapX):4.3-Math.abs(gapZ),otherVelocity:{x:0,z:velocity},restitution:.12});};
for(let i=0;i<trafficCount($('traffic').value);i++){const pose=trafficPose(i,time,s.position.z,width);obstacle(pose.x,s.position.z+pose.z,pose.velocity);}
for(let i=0;i<16;i++){const x=(i%2?1:-1)*(width-1.3),base=115+i*51,z=((base-s.position.z+70)%loc.length+loc.length)%loc.length-70;obstacle(x,s.position.z+z);}
}
function tick(t){const dt=Math.max(0,(t-last)/1000||0);last=t;
if(playing&&!paused){renderState=simulation.advance(dt,inputFromKeys(keys,$('transmission').value==='manual'),(s,h,simTime)=>{time=simTime;contacts(s);let cp=Math.floor(s.distance/250);if(cp>prevCheckpoint){s.score+=500;prevCheckpoint=cp;}s.checkpoint=cp%8+1;});state=simulation.state;controls=simulation.controls;}else{simulation.accumulator=0;simulation.previous=structuredClone(simulation.state);renderState=simulation.state;}
render(dt);audio.update(state,controls,paused||optionsOpen||introActive,$('sound').value==='on');$('speed').textContent=String(Math.round(Math.abs(state.speed)*(mph?2.237:3.6))).padStart(3,'0');$('gear').textContent=state.speed<-.3?'R':state.gear;$('score').textContent=String(Math.floor(state.score)).padStart(6,'0');$('distance').textContent=(state.distance/1000).toFixed(2);$('top').textContent=Math.round(state.top*(mph?2.237:3.6));$('drift').textContent=Math.floor(state.drift);$('rpmBar').style.width=Math.min(100,state.rpm/8000*100)+'%';$('boostBar').style.width=state.boost+'%';$('damageBar').style.width=state.damage*100+'%';$('checkpoint').textContent=`CHECKPOINT ${state.checkpoint} / 8`;$('speedlines').style.opacity=playing?Math.max(0,(Math.abs(state.speed)-40)/100):0;requestAnimationFrame(tick);}requestAnimationFrame(tick);
window.NightView={start,pause,reset,openOptions,closeOptions,getState:()=>({...state,playing,paused,optionsOpen,mode,location:locationId,car,intro:introActive})};
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_driving_session',description:'Read current vehicle, mode and arcade session statistics.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.NightView.getState()});document.modelContext.registerTool({name:'start_arcade_drive',description:'Start a fresh free-drive session at the selected modeled location with a chosen vehicle.',inputSchema:{type:'object',properties:{car:{type:'integer',minimum:0,maximum:2}},required:['car'],additionalProperties:false},execute:input=>{if(!Number.isInteger(input.car)||input.car<0||input.car>2)throw Error('Car must be 0, 1 or 2.');document.querySelector(`[data-car="${input.car}"]`).click();chooseMode('demo');car=input.car;mode='demo';start();return window.NightView.getState();}});}catch(e){console.warn('WebMCP unavailable',e);}}

start();paused=true;document.body.classList.add('booting');setTimeout(dismissIntro,2400);
